begin;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'FAILED: %',label; end if; raise notice 'PASS: %',label; end $$;
insert into auth.users(id,is_anonymous) values('40000000-0000-4000-8000-000000000001',false),('40000000-0000-4000-8000-000000000002',true);
set local role service_role;
do $$
declare owner constant uuid:='40000000-0000-4000-8000-000000000001'; car constant uuid:='40000000-0000-4000-8000-000000000002';
 c jsonb:=jsonb_build_object('source','pleos','observed_at',now(),'passenger_state','alone','passenger_source','user_assertion','trip_distance_m',1200,'latitude',37,'longitude',127,'place_label','회사');
 v jsonb; s uuid; d uuid; turn_id uuid; request uuid:=gen_random_uuid();
begin
 v:=private.filtered_context(c,false);
 perform pg_temp.assert_true(v->>'passenger_state'='alone' and v->>'passenger_source'='user_assertion','manual solo choice survives missing sensor consent');
 perform pg_temp.assert_true((select count(*)=4 from jsonb_object_keys(v)),'manual-only context has exactly four allowed fields');
 perform pg_temp.assert_true(not(v?'trip_distance_m') and not(v?'latitude') and not(v?'place_label'),'sensor location and trip fields stripped without consent');
 v:=private.filtered_context(c,true);
 perform pg_temp.assert_true(v->>'trip_distance_m'='1200' and not(v?'latitude') and not(v?'longitude'),'allowed sensor fields survive but raw coordinates never do');
 perform pg_temp.assert_true(private.filtered_context(c||'{"passenger_source":"pleos_seat"}',false)='{}','sensor-detected alone requires sensor consent');
 perform pg_temp.assert_true(private.filtered_context(c||'{"passenger_state":"occupied"}',false)='{}','manual assertion is only the explicit solo choice');
 perform pg_temp.assert_true(private.filtered_context(c||jsonb_build_object('observed_at',now()-interval '121 seconds'),false)='{}','stale manual choice is not reused');
 perform pg_temp.assert_true(private.filtered_context(c||jsonb_build_object('observed_at',now()+interval '11 seconds'),false)='{}','future context rejected');
 perform pg_temp.assert_true(private.filtered_context(c||'{"observed_at":"not a timestamp"}',false)='{}','malformed timestamp fails closed');
 perform public.doran_command(owner,'profiles.get');
 perform public.doran_command(owner,'profiles.update','{"version":1,"consent_ai":true}');
 v:=public.doran_command(car,'devices.bootstrap'); d:=(v->'device'->>'id')::uuid;
 update public.devices set owner_id=owner,active=true where id=d;
 v:=public.doran_command(car,'sessions.create',jsonb_build_object('request_id',gen_random_uuid(),'vehicle_context',c));s:=(v->'session'->>'id')::uuid;
 perform pg_temp.assert_true(v->'session'->'vehicle_context'->>'passenger_source'='user_assertion','session creation keeps manual choice');
 v:=public.doran_worker('context.get',jsonb_build_object('owner_id',owner,'session_id',s));
 perform pg_temp.assert_true(v->'context'->>'passenger_state'='alone' and not(v->'context'?'trip_distance_m'),'AI context receives only manual choice without sensor consent');
 v:=public.doran_command(car,'sessions.turn',jsonb_build_object('session_id',s,'request_id',request,'text','오늘 이야기를 나누자','vehicle_context',c));turn_id:=(v->'turn'->>'id')::uuid;
 perform pg_temp.assert_true(v->'session'->'vehicle_context'->>'passenger_state'='alone','new turn keeps manual solo context');
 perform public.doran_worker('turns.fail',jsonb_build_object('turn_id',turn_id));
 v:=public.doran_command(car,'sessions.turn',jsonb_build_object('session_id',s,'request_id',request,'text','오늘 이야기를 나누자','vehicle_context',c));
 perform pg_temp.assert_true(v->'session'->'vehicle_context'->>'passenger_source'='user_assertion','failed turn retry also keeps manual-only context');
 perform public.doran_command(owner,'profiles.update','{"version":2,"consent_vehicle":true}');
 v:=public.doran_command(car,'sessions.create',jsonb_build_object('request_id',gen_random_uuid(),'vehicle_context',c));s:=(v->'session'->>'id')::uuid;
 perform pg_temp.assert_true(v->'session'->'vehicle_context'?'trip_distance_m','sensor consent enables allowed context');
 perform public.doran_command(owner,'profiles.update','{"version":3,"consent_vehicle":false}');
 v:=public.doran_command(car,'sessions.get',jsonb_build_object('session_id',s));
 perform pg_temp.assert_true(v->'session'->'vehicle_context'->>'passenger_source'='user_assertion' and not(v->'session'->'vehicle_context'?'trip_distance_m'),'revoking sensor consent retains explicit choice and purges sensor facts');
end $$;
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000001","is_anonymous":true}',true);
select pg_temp.assert_true((select count(*)=0 from public.profiles),'explicit anonymous JWT cannot pass owner read policy');
reset role;
select pg_temp.assert_true(not has_function_privilege('authenticated','private.filtered_context(jsonb,boolean)','EXECUTE'),'clients cannot invoke private context helper');
rollback;
